#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""Convert fork_compare progress.json files to per-case CSV.

Reads the compare output directories produced by fork_compare.py and
writes one CSV per run (case id, fork verdict, stock verdict, recorded
verdict where one exists, and the match flag).

Usage:
    python3 -I convert_progress.py --progress-dir DIR --out-dir DIR

Both arguments are required; there are no defaults and no paths are
derived from this script's location.
"""
import argparse
import csv
import json
import os
import sys

_ap = argparse.ArgumentParser(
    description="progress.json -> per-case CSV converter (no defaults)")
_ap.add_argument("--progress-dir", required=True, metavar="PATH",
                 help="directory containing the per-run compare "
                      "subdirectories, each with a progress.json "
                      "(required, no default)")
_ap.add_argument("--out-dir", required=True, metavar="PATH",
                 help="output directory for the CSV files "
                      "(required, no default)")
a = _ap.parse_args()

os.makedirs(a.out_dir, exist_ok=True)

RUNS = [
    # (compare subdir, arm label, pass label)
    ("dot7-h1-compare",  "monerodato.7",  "H1"),
    ("dot7-h2-compare",  "monerodato.7",  "H2"),
    ("proto-h1-compare", "bpp-split prototype", "H1"),
    ("proto-h2-compare", "bpp-split prototype", "H2"),
    ("dot9-h1-compare",  "monerodato.9 candidate", "H1"),
    ("dot9-h2-compare",  "monerodato.9 candidate", "H2"),
]

for d, arm, hf in RUNS:
    p = os.path.join(a.progress_dir, d, "progress.json")
    if not os.path.exists(p):
        print(f"SKIP {d}: no progress.json", file=sys.stderr)
        continue
    with open(p) as f:
        prog = json.load(f)
    out_csv = os.path.join(a.out_dir, f"{d}.csv")
    n = 0
    with open(out_csv, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["case_id", "fork_verdict", "stock_verdict",
                    "recorded_verdict", "match"])
        for cid, r in prog.items():
            stock, fork, rec = r.get("stock"), r.get("fork"), r.get("recorded")
            match = int(stock == fork and (rec is None or stock == rec))
            w.writerow([cid, stock, fork, rec if rec is not None else "n/a", match])
            n += 1
    print(f"{d}: {n} cases -> {os.path.basename(out_csv)}")

# parm-mut runs: no recorded third party; match = stock==fork
for d in ("parm-mut-compare", "parm-mut-proto-compare", "dot9-parm-mut-compare"):
    p = os.path.join(a.progress_dir, d, "progress.json")
    if not os.path.exists(p):
        print(f"SKIP {d}", file=sys.stderr)
        continue
    with open(p) as f:
        prog = json.load(f)
    out_csv = os.path.join(a.out_dir, f"{d}.csv")
    n = 0
    with open(out_csv, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["case_id", "fork_verdict", "stock_verdict", "match"])
        for cid, r in prog.items():
            w.writerow([cid, r.get("fork"), r.get("stock"),
                        int(r.get("stock") == r.get("fork"))])
            n += 1
    print(f"{d}: {n} cases -> {os.path.basename(out_csv)}")
